import { execFileSync } from 'node:child_process';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';

/**
 * Deterministic local media for production-spine tests, generated with ffmpeg's built-in test sources into a temp
 * directory outside the repository. Nothing is generated by a provider and nothing is committed.
 *
 *   video  testsrc2 pattern, 270×480 (9:16), 24 fps, 5 s, no audio, H.264
 *   frame  one flat 270×480 PNG standing in for a founder-supplied reference photograph
 */
export type SpineFixtureMedia = { dir: string; video: Uint8Array; frame: Uint8Array; videoMeta: { width: 270; height: 480; fps: 24; seconds: 5; frames: 120 } };

export function tempDir(prefix: string) {
  return fs.mkdtempSync(path.join(os.tmpdir(), prefix));
}

export function makeSpineFixtureMedia(dir = tempDir('site00-spine-fixture-')): SpineFixtureMedia {
  const video = path.join(dir, 'TEST_FIXTURE_take.mp4');
  const frame = path.join(dir, 'TEST_FIXTURE_reference.png');
  const ff = (args: string[]) => execFileSync('ffmpeg', ['-v', 'error', '-y', ...args], { stdio: 'pipe' });
  ff(['-f', 'lavfi', '-i', 'testsrc2=size=270x480:rate=24:duration=5', '-c:v', 'libx264', '-preset', 'ultrafast', '-threads', '1', '-pix_fmt', 'yuv420p', '-bitexact', '-map_metadata', '-1', video]);
  ff(['-f', 'lavfi', '-i', 'color=c=0x8a5a2b:size=270x480', '-frames:v', '1', '-bitexact', frame]);
  return { dir, video: new Uint8Array(fs.readFileSync(video)), frame: new Uint8Array(fs.readFileSync(frame)), videoMeta: { width: 270, height: 480, fps: 24, seconds: 5, frames: 120 } };
}

/** A clock that starts at a fixed instant and advances one second per reading. */
export function steppingClock(start = '2026-10-25T13:00:00Z') {
  let t = Date.parse(start);
  return () => {
    const iso = new Date(t).toISOString().replace('.000Z', 'Z');
    t += 1000;
    return iso;
  };
}
